<script setup lang="ts">
type Column={key:string,label:string,width?:number,minWidth?:number,flex?:number,align?:'left'|'right'|'center'}
const props=defineProps<{columns:Column[],rows:any[],rowKey:string,storageKey:string,fillHeight?:boolean,layoutVersion?:number,leadingColumns?:string[]}>()
const order=ref<string[]>(props.columns.map(c=>c.key)),widths=ref<Record<string,number>>({}),hidden=ref<string[]>([]),dragging=ref(''),dropTarget=ref(''),columnMenu=ref<HTMLDetailsElement|null>(null)
const shown=computed(()=>order.value.filter(key=>!hidden.value.includes(key)).map(key=>props.columns.find(c=>c.key===key)).filter(Boolean) as Column[])
const width=(c:Column)=>widths.value[c.key]||c.width||140
const grid=ref<HTMLElement|null>(null),availableWidth=ref(0)
let observer:ResizeObserver|undefined
// 多余宽度留给未手调的长文本列，数字列保持紧凑。
const fittedWidths=computed(()=>{const total=shown.value.reduce((sum,c)=>sum+width(c),0),extra=Math.max(0,availableWidth.value-total),weight=shown.value.reduce((sum,c)=>sum+(widths.value[c.key]?0:c.flex||0),0);return Object.fromEntries(shown.value.map(c=>[c.key,width(c)+(weight&&!widths.value[c.key]?extra*(c.flex||0)/weight:0)]))})
const tableWidth=computed(()=>shown.value.reduce((sum,c)=>sum+(fittedWidths.value[c.key]||width(c)),0))
function persist(){try{localStorage.setItem(props.storageKey,JSON.stringify({order:order.value,widths:widths.value,hidden:hidden.value,layoutVersion:props.layoutVersion||0}))}catch{}}
// 使用原目标位置，使向左、向右拖动都能移动整列，列宽与内容随列保留。
function move(key:string,target:string){const index=order.value.indexOf(target);if(!key||key===target||index<0||!order.value.includes(key))return;const next=order.value.filter(c=>c!==key);next.splice(index,0,key);order.value=next;persist()}
function dragStart(c:Column,event:DragEvent){if((event.target as HTMLElement).closest('button,input,select,[role=combobox],.resize-column')){event.preventDefault();return}dragging.value=c.key;dropTarget.value='';event.dataTransfer?.setData('text/plain',c.key);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function dragEnd(){dragging.value='';dropTarget.value=''}
function dropColumn(target:string){move(dragging.value,target);dragEnd()}
const columnClass=(key:string)=>({'column-dragging':dragging.value===key,'column-target':!!dragging.value&&dragging.value!==key&&dropTarget.value===key})
function reset(){order.value=props.columns.map(c=>c.key);widths.value={};hidden.value=[];persist()}
function setVisible(key:string,visible:boolean){if(!visible&&shown.value.length<=1)return;hidden.value=visible?hidden.value.filter(k=>k!==key):[...new Set([...hidden.value,key])];persist()}
function showAll(){hidden.value=[];persist()}
function closeColumnMenu(event:MouseEvent){if(columnMenu.value&&!columnMenu.value.contains(event.target as Node))columnMenu.value.open=false}
function keyboard(c:Column,e:KeyboardEvent){if(e.target!==e.currentTarget)return;if(!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const keys=shown.value.map(column=>column.key),i=keys.indexOf(c.key),j=i+(e.key==='ArrowLeft'?-1:1);if(j<0||j>=keys.length)return;move(c.key,keys[j]!)}
function resize(c:Column,e:PointerEvent){e.preventDefault();e.stopPropagation();const x=e.clientX,initial=fittedWidths.value[c.key]||width(c),target=e.currentTarget as HTMLElement;target.setPointerCapture(e.pointerId);const change=(event:PointerEvent)=>{widths.value={...widths.value,[c.key]:Math.max(c.minWidth||90,Math.min(900,initial+event.clientX-x))}};const stop=()=>{target.removeEventListener('pointermove',change);target.removeEventListener('pointerup',stop);target.removeEventListener('pointercancel',stop);persist()};target.addEventListener('pointermove',change);target.addEventListener('pointerup',stop);target.addEventListener('pointercancel',stop)}
onMounted(()=>{document.addEventListener('click',closeColumnMenu);if(grid.value){observer=new ResizeObserver(()=>{availableWidth.value=grid.value?.clientWidth||0});observer.observe(grid.value);availableWidth.value=grid.value.clientWidth}try{const saved=JSON.parse(localStorage.getItem(props.storageKey)||'{}'),known=props.columns.map(c=>c.key);if(Array.isArray(saved.order))order.value=[...new Set<string>(saved.order.filter((k:any)=>known.includes(k))),...known.filter(k=>!saved.order.includes(k))];if(Array.isArray(saved.hidden))hidden.value=[...new Set<string>(saved.hidden.filter((key:any)=>known.includes(key)))].slice(0,Math.max(0,known.length-1));if(saved.widths&&typeof saved.widths==='object')for(const key of known){const value=Number(saved.widths[key]);if(Number.isFinite(value)&&value>=(props.columns.find(c=>c.key===key)?.minWidth||90)&&value<=900)widths.value[key]=value}if(props.layoutVersion&&saved.layoutVersion!==props.layoutVersion){const leading=(props.leadingColumns||[]).filter(key=>known.includes(key));order.value=[...leading,...order.value.filter(key=>!leading.includes(key))];persist()}}catch{}})
onBeforeUnmount(()=>{document.removeEventListener('click',closeColumnMenu);observer?.disconnect()})
watch(()=>props.columns.map(c=>c.key),known=>{order.value=[...order.value.filter(key=>known.includes(key)),...known.filter(key=>!order.value.includes(key))];hidden.value=hidden.value.filter(key=>known.includes(key)).slice(0,Math.max(0,known.length-1))})
</script>
<template>
 <div :class="{'production-grid-fill':fillHeight}"><div class="grid-toolbar flex justify-end items-center gap-4 mb-2"><details ref="columnMenu" class="column-menu" @keydown.esc="columnMenu&&(columnMenu.open=false)"><summary>显示列 <span class="text-muted">{{ shown.length }}/{{ columns.length }}</span><span aria-hidden="true">▾</span></summary><div class="column-options" role="group" aria-label="选择显示列"><div class="flex justify-between gap-3 mb-2"><strong>选择显示的列</strong><button type="button" class="text-primary" @click="showAll">全选列</button></div><label v-for="c in columns" :key="c.key"><input type="checkbox" :checked="!hidden.includes(c.key)" :disabled="shown.length===1&&!hidden.includes(c.key)" @change="setVisible(c.key,($event.target as HTMLInputElement).checked)">{{ c.label }}</label></div></details><button class="text-sm text-muted" type="button" @click="reset">恢复默认列</button></div><div ref="grid" class="production-grid" tabindex="0" aria-label="生产表格，可左右滚动">
  <table :style="{width:tableWidth+'px',minWidth:columns.some(c=>c.flex)?'0':'100%'}"><colgroup><col v-for="c in shown" :key="c.key" :style="{width:(fittedWidths[c.key]||width(c))+'px'}"></colgroup>
   <thead><tr><th v-for="c in shown" :key="c.key" draggable="true" tabindex="0" :data-column="c.key" :class="columnClass(c.key)" :style="{textAlign:c.align||'left'}" :aria-label="c.label+'，拖动整列，Alt加左右键移动'" @keydown="keyboard(c,$event)" @dragstart="dragStart(c,$event)" @dragend="dragEnd" @dragover.prevent="dropTarget=c.key" @drop.prevent="dropColumn(c.key)">
    <span class="column-name">{{ c.label }}</span><slot :name="'filter-'+c.key"/><span class="resize-column" role="separator" aria-orientation="vertical" :aria-label="'调整'+c.label+'列宽'" @pointerdown="resize(c,$event)" @dragstart.prevent/>
   </th></tr></thead>
   <tbody><tr v-for="r in rows" :key="r[rowKey]"><td v-for="c in shown" :key="c.key" :data-column="c.key" :class="columnClass(c.key)" :style="{textAlign:c.align||'left'}" :title="String(r[c.key]??'')" @dragover.prevent="dropTarget=c.key" @drop.prevent="dropColumn(c.key)"><slot :name="'cell-'+c.key" :row="r">{{ r[c.key]??'-' }}</slot></td></tr><tr v-if="!rows.length"><td :colspan="shown.length" class="text-center py-8">暂无符合条件的记录</td></tr></tbody>
  </table>
 </div></div>
</template>
<style scoped>
.production-grid{--grid-line:#b8c4d0;overflow:auto;max-width:100%;border:1px solid var(--grid-line);border-radius:0}.production-grid table{table-layout:fixed;border-collapse:collapse;min-width:100%;font-size:14px}.production-grid th,.production-grid td{padding:10px 8px;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;border:1px solid var(--grid-line);height:52px}.production-grid th{font-size:12px;position:relative;background:var(--ui-bg-elevated);vertical-align:top;cursor:grab;font-weight:600}.column-name{display:block;margin-bottom:6px}.resize-column{position:absolute;right:0;top:0;width:7px;height:100%;cursor:col-resize;touch-action:none}.resize-column:hover{background:var(--ui-primary)}.production-grid tbody tr:hover{background:var(--ui-bg-elevated)}.production-grid .column-dragging{background:color-mix(in srgb,var(--ui-primary) 14%,var(--ui-bg));cursor:grabbing}.production-grid .column-target{box-shadow:inset 3px 0 var(--ui-primary)}
.production-grid-fill{display:flex;flex-direction:column;min-height:0}.production-grid-fill .grid-toolbar{flex-shrink:0}.production-grid-fill .production-grid{flex:1;min-height:0}.production-grid-fill th{position:sticky;top:0;z-index:1}
.column-menu{position:relative}.column-menu summary{display:flex;align-items:center;gap:8px;cursor:pointer;border:1px solid var(--b-divider-strong);padding:7px 12px;border-radius:4px;font-size:14px;list-style:none}.column-menu summary::-webkit-details-marker{display:none}.column-options{position:absolute;right:0;top:calc(100% + 6px);z-index:30;min-width:240px;max-height:360px;overflow:auto;padding:12px;background:var(--ui-bg);border:1px solid var(--b-divider-strong);border-radius:6px;box-shadow:0 8px 24px #0002}.column-options label{display:flex;align-items:center;gap:10px;padding:6px 2px;white-space:nowrap;cursor:pointer}.column-options input{width:16px;height:16px;accent-color:var(--ui-primary)}
</style>
